ask_age.py.src:
while True:
    text = input("How old are you? ")
    try:
        age = int(text)
    except ValueError:
        print("Not a whole number. Try again.")
    else:
        if age >= 0:
            break
        print("Ages start at 0. Try again.")
print("Next year you will be", age + 1)

