    bill = bill + line_total(item, 2)
    print("Added", item)
print("Bill:", bill)

boss_err.py.src:
stock = {"apples": 3}

def take(item, n):
    left = stock[item] - n
    if left < 0:
        raise ValueError("not enough " + item)
    stock[item] = left

