share.py.src:
def share(cookies, friends):
    try:
        each = int(cookies) // int(friends)
    except ValueError:
        return "numbers only, please"
    except ZeroDivisionError:
        return "nobody to share with"
    return f"{each} each"

print(share("12", "4"))
print(share("12", "four"))
print(share("12", "0"))

